const bin = $input.first().binary?.data;

if (!bin) {
  throw new Error('Keine Binärdatei unter binary.data gefunden');
}

const payload = $('Payload Valid?').first().json;
const uservorname = payload.normalized.uservorname;
const to = payload.normalized.email;
const report = payload.normalized.report;

let subject = "";
let text = "";
let html = "";
let report_name = "";
let workflow = "";

switch (report) {
  case "bestellungen":
    subject = `Report Bestellungen ${$now.toFormat('yyyy-LL-dd')}`;
    text = "Im Anhang befindet sich der aktuelle Bestellreport.";
    html = `<p>Hallo ${uservorname},</p>
            <p>im Anhang befindet sich der aktuelle <b>Bestellreport</b> für die letzten vier Wochen.</p>
            <p>Erzeugt am: ${$now.toFormat('dd.LL.yyyy HH:mm:ss')}</p>`;
    report_name = "vi_report_bestellungen";
    workflow = "Bestellreport Export";
    break;

  case "lieferungen":
    subject = `Report Warenannahmen ${$now.toFormat('yyyy-LL-dd')}`;
    text = "Im Anhang befindet sich der aktuelle Warenannahmereport.";
    html = `<p>Hallo ${uservorname},</p>
            <p>im Anhang befindet sich der aktuelle <b>Warenannahmereport</b> für die letzten vier Wochen.</p>
            <p>Erzeugt am: ${$now.toFormat('dd.LL.yyyy HH:mm:ss')}</p>`;
    report_name = "vi_report_lieferungen";
    workflow = "Warenannahmereport Export";
    break;

  case "rechnungen":
    subject = `Report Rechnungen ${$now.toFormat('yyyy-LL-dd')}`;
    text = "Im Anhang befindet sich der aktuelle Rechnungenreport.";
    html = `<p>Hallo ${uservorname},</p>
            <p>im Anhang befindet sich der aktuelle <b>Rechnungenreport</b> für die letzten vier Wochen.</p>
            <p>Erzeugt am: ${$now.toFormat('dd.LL.yyyy HH:mm:ss')}</p>`;
    report_name = "vi_report_rechnungen";
    workflow = "Rechnungenreport Export";
    break;

  default:
    throw new Error(`Unbekannter Report-Typ: ${report}`);
}

const finalFilename =
  bin.fileName ||
  `report_${report}_${$now.toFormat('yyyy-LL-dd_HH-mm-ss')}.xlsx`;

return [
  {
    json: {
      to: [to],
      cc: [],
      bcc: [],
      from: "infofee@euroimmun.de",
      from_name: "BestellFee Reporting",
      subject,
      text,
      html,
      attachments: [
        {
          filename: finalFilename,
          mimeType: bin.mimeType || "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
          contentBase64: bin.data
        }
      ],
      meta: {
        report_name,
        workflow,
        generated_at: $now.toISO(),
        file_name: finalFilename
      }
    }
  }
];

const body = $('Webhook').first().json.body || {};
const uservorname = $input.first().json.UserVorname;
const email = $input.first().json.UserMail;
const errors = [];

// ---- EMAIL VALIDATION ----
const s = String(email || '').trim();
const parts = s.toLowerCase().split('@');

const valid =
  parts.length === 2 &&
  ['euroimmun.de', 'euroimmun.com', 'revvity.com'].includes(parts[1]);

if (!valid) {
  errors.push(`Invalid or not allowed recipient: ${email}`);
}

// ---- REPORT VALIDATION ----
const allowedReports = ['vi_report_bestellungen', 'vi_report_rechnungen', 'vi_report_lieferungen', 'vi_report_bestellungen_vr', 'vi_report_rechnungen_vr'];
const normalizedReport = typeof body.report === 'string' ? 'vi_report_' + body.report.trim().toLowerCase() : null;

if (!normalizedReport || normalizedReport === '') {
  errors.push('Field "report" must be a non-empty string');
} else {
  if (!allowedReports.includes(normalizedReport)) {
    errors.push(`Invalid report type: ${normalizedReport}`);
  }
}
// ---- REPORT VALIDATION ----
const allowedTargets = ['download', 'mail'];
const normalizedTarget = typeof body.target === 'string' ? body.target.trim().toLowerCase() : null;

if (!normalizedTarget || normalizedTarget === '') {
  errors.push('Field "target" must be a non-empty string');
} else {
  if (!allowedTargets.includes(normalizedTarget)) {
    errors.push(`Invalid report type: ${normalizedTarget}`);
  }
}

// ---- FILTERDATE VALIDATION ----

function parseGermanDate(value, fieldName) {

  if (typeof value !== 'string' || value.trim() === '') {
    errors.push(`Field "${fieldName}" must be a non-empty date string DD.MM.YYYY`);
    return null;
  }

  const s = value.trim();

  // Format prüfen
  if (!/^\d{2}\.\d{2}\.\d{4}$/.test(s)) {
    errors.push(`Field "${fieldName}" must use format DD.MM.YYYY`);
    return null;
  }

  const [dd, mm, yyyy] = s.split('.').map(Number);

  // UTC verhindert TZ-Probleme
  const d = new Date(Date.UTC(yyyy, mm - 1, dd));

  // Prüft echte Kalenderdaten (31.02. etc.)
  if (
    d.getUTCFullYear() !== yyyy ||
    d.getUTCMonth() !== (mm - 1) ||
    d.getUTCDate() !== dd
  ) {
    errors.push(`Field "${fieldName}" is not a valid calendar date`);
    return null;
  }

  return d;
}

const fromDate = parseGermanDate(body.fromdate, 'fromdate');
const toDate   = parseGermanDate(body.todate, 'todate');

if (fromDate && toDate) {

  const today = new Date();
  const todayUtc = new Date(Date.UTC(
      today.getUTCFullYear(),
      today.getUTCMonth(),
      today.getUTCDate()
  ));

  // From <= To
  if (fromDate > toDate) {
    errors.push('"fromdate" must be before or equal to "todate"');
  }

  // To <= today
  if (toDate > todayUtc) {
    errors.push('"todate" may not be in the future');
  }

  // Max 2 Jahre Abstand
  const maxRangeStart = new Date(toDate);
  maxRangeStart.setUTCFullYear(
      maxRangeStart.getUTCFullYear() - 2
  );

  if (fromDate < maxRangeStart) {
    errors.push('Date interval may not exceed 2 years');
  }
}

// Normalisierung nach YYYY-MM-DD
const normalizedFromDate =
  fromDate
   ? fromDate.toISOString().slice(0,10)
   : null;

const normalizedToDate =
  toDate
   ? toDate.toISOString().slice(0,10)
   : null;

// Validiere Datum -> From <= To <= heute; Max interval = 2 Jahre

// ---- RESULT ----
return [{
  json: {
    valid: errors.length === 0,
    errors,
    body,
    normalized: {
      report: normalizedReport,
      target: normalizedTarget,
      fromdate: normalizedFromDate,
      todate: normalizedToDate,
      uservorname: uservorname,
      email: email
    }
  }
}];

